#!/usr/bin/env node
// Regenerates the readable 109-level reference in Research/03-109-levels/ from the
// single source of truth, backend/src/data/skillLevelMap.json.
//   node scripts/export-levels-docs.js
// Outputs: levels-and-subskills.csv (one row per level x subskill) and all-levels.md.
// Do not edit those two files by hand; change the JSON and re-run this script.

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const map = JSON.parse(fs.readFileSync(path.join(root, 'backend/src/data/skillLevelMap.json'), 'utf8'));
const outDir = path.join(root, 'Research/03-109-levels');

const levels = Object.values(map.levels).sort((a, b) => a.levelNumber - b.levelNumber);
const q = (s) => `"${String(s).replace(/"/g, '""')}"`;

// CSV: one row per (level, subskill of each skill the level touches)
const header = ['levelNumber', 'levelId', 'conceptId', 'stage', 'capability', 'skillId', 'skillName', 'subskillId', 'subskillName'];
const rows = [header.map(q).join(',')];
for (const lv of levels) {
  for (const skillId of lv.skills) {
    const sk = map.skills[skillId];
    for (const sub of sk.subskills) {
      rows.push([lv.levelNumber, `L${lv.levelNumber}`, lv.sCode, lv.stage, lv.capability, skillId, sk.name, sub.id, sub.name].map(q).join(','));
    }
  }
}
fs.writeFileSync(path.join(outDir, 'levels-and-subskills.csv'), '﻿' + rows.join('\n') + '\n');

// Markdown overview, grouped by stage
const stages = [...new Set(levels.map((l) => l.stage))];
let md = `# All ${levels.length} FLN levels, stage by stage\n\n`;
md += '> Generated by `node scripts/export-levels-docs.js` from `backend/src/data/skillLevelMap.json`. Do not edit by hand.\n\n';
md += 'Skills are the ones the level touches. Skill names are in [skills-and-subskills.md](./skills-and-subskills.md).\n\n';
for (const st of stages) {
  const inStage = levels.filter((l) => l.stage === st);
  md += `## ${map.stageLabels[st] || st} (code name \`${st}\`): levels ${inStage[0].levelNumber}-${inStage[inStage.length - 1].levelNumber} (${inStage.length})\n\n`;
  md += '| Level | Concept ID | What the level is about | Skills |\n|---|---|---|---|\n';
  for (const l of inStage) md += `| L${l.levelNumber} | ${l.sCode} | ${l.capability} | ${l.skills.join(', ')} |\n`;
  md += '\n';
}
fs.writeFileSync(path.join(outDir, 'all-levels.md'), md);

// Markdown skill list with the levels each skill appears in
const usedIn = {};
for (const l of levels) for (const s of l.skills) (usedIn[s] ||= []).push(l.levelNumber);
let sm = `# The ${Object.keys(map.skills).length} skills and their subskills\n\n`;
sm += '> Generated by `node scripts/export-levels-docs.js` from `backend/src/data/skillLevelMap.json`. Do not edit by hand.\n\n';
for (const [id, sk] of Object.entries(map.skills)) {
  sm += `## ${id}: ${sk.name}\n\nDomain: ${sk.domain}. Appears in levels: ${(usedIn[id] || []).map((n) => 'L' + n).join(', ') || 'none'}.\n\n`;
  for (const sub of sk.subskills) sm += `- \`${sub.id}\` ${sub.name}\n`;
  sm += '\n';
}
fs.writeFileSync(path.join(outDir, 'skills-and-subskills.md'), sm);
console.log(`levels=${levels.length} csvRows=${rows.length - 1} skills=${Object.keys(map.skills).length}`);
